class MinStack:
    """A stack that reports its smallest value."""

    def __init__(self):
        self._items = []

    def push(self, value):
        if self._items:
            current_min = min(value, self._items[-1][1])
        else:
            current_min = value
        self._items.append((value, current_min))

    def pop(self):
        return self._items.pop()[0]

    def top(self):
        return self._items[-1][0]

    def get_min(self):
        if not self._items:
            raise ValueError("get_min() from empty stack")
        return self._items[-1][1]

    def __len__(self):
        return len(self._items)
